// No imports: `apps/mobile/scripts/make-alarm-tone.mjs` loads this file directly with Node.

/**
 * The alarm tone, shared by the web (Web Audio) and the WAV the phone plays
 * (generated by `apps/mobile/scripts/make-alarm-tone.mjs`): two-tone beeps,
 * a pause, repeated. Frequencies in Hz, times in ms; `freq: 0` is silence.
 */
export const ALARM_TONE: { freq: number; ms: number }[] = [
  { freq: 988, ms: 140 },
  { freq: 0, ms: 60 },
  { freq: 1319, ms: 140 },
  { freq: 0, ms: 60 },
  { freq: 988, ms: 140 },
  { freq: 0, ms: 60 },
  { freq: 1319, ms: 140 },
  { freq: 0, ms: 560 },
];
/** One loop of the tone, ms. */
export const ALARM_TONE_MS = ALARM_TONE.reduce((s, p) => s + p.ms, 0);
/** Vibration that goes with one loop (Android pattern: wait, buzz, wait, buzz…). */
export const ALARM_VIBRATION = [0, 400, 200, 400, 600];
